public static int findNthLeapYear(int Y, int N) {
    // Check if the inputs are valid
    if (Y < 1 || N < 1) {
        throw new IllegalArgumentException("Year and position must be positive integers");
    }

    // Find the next leap year after the start year
    int leapYear = Y + 4 - (Y % 4);

    // Check if the position is less than or equal to the number of leap years between the start year and the next leap year
    if (N <= (leapYear - Y) / 4) {
        return Y + (N - 1) * 4;
    } else {
        return leapYear + (N - (leapYear - Y) / 4) * 4;
    }
}

