    for (String string : strings) {
        longestStringLength = Math.max(longestStringLength, string.length());
    }

    // Create a set to store the unique strings in the list
    Set<String> uniqueStrings = new HashSet<>(strings);

    // Iterate over the unique strings in the list
    for (String string : uniqueStrings) {
        // Find the length of the string
        int stringLength = string.length();

        // Check if the string or its inverse can be found as a substring of any of the other strings in the list
        for (String otherString : strings) {
            if (otherString.contains(string) || otherString.contains(string.substring(stringLength - 1))) {
                // If the string or its inverse is found, return its length
                return stringLength;
            }
        }
    }

    // If no string or its inverse can be found as a substring, return 0
    return 0;
}

