public int minCostClimbingStairs(int[] cost) {
    int minCost = Integer.MAX_VALUE;
    int startIndex = 0;
    int endIndex = cost.length - 1;

    while (startIndex <= endIndex) {
        int currentCost = 0;
        for (int i = startIndex; i <= endIndex; i++) {
            currentCost += cost[i];
        }

        if (currentCost < minCost) {
            minCost = currentCost;
            startIndex++;
        } else {
            startIndex = endIndex + 1;
        }
    }

    return minCost;
}

