public static int minPerfectSquareSum(int n) {
    // Initialize a list to store the perfect square numbers
    List<Integer> perfectSquares = new ArrayList<>();

    // Loop through the integers from 1 to sqrt(n)
    for (int i = 1; i <= Math.sqrt(n); i++) {
        // Check if i is a perfect square
        if (i * i <= n) {
            // If i is a perfect square, add it to the list
            perfectSquares.add(i * i);
        }
    }

    // Initialize a variable to store the minimum number of perfect square numbers
    int minNum = -1;

    // Loop through the perfect square numbers in the list
    for (int i = 0; i < perfectSquares.size(); i++) {
        // Initialize a variable to store the number of perfect square numbers needed for the current sum
        int numNeeded = 0;

        // Loop through the perfect square numbers starting from the current one
        for (int j = i; j < perfectSquares.size(); j++) {
            // Check if the current sum is less than or equal to n
            if (perfectSquares.get(i) + perfectSquares.get(j) <= n) {
                // If the current sum is less than or equal to n, increment the number of perfect square numbers needed
                numNeeded++;
            } else {
                // If the current sum is greater than n, break the inner loop
                break;
            }
        }

        // Check if the current number of perfect square numbers needed is less than the minimum number
        if (numNeeded < minNum || minNum == -1) {
            // If the current number of perfect square numbers needed is less than the minimum number, update the minimum number
            minNum = numNeeded;
        }
    }

    return minNum;
}

